import pandas as pd

def clean(df):
    df = df.copy()

    if 'species' in df.columns:
        df['species'] = df['species'].astype('string').str.strip().str.title()

    if 'island' in df.columns:
        df['island'] = df['island'].astype('string').str.strip()

    if 'sex' in df.columns:
        df['sex'] = df['sex'].astype('string').str.strip().str.lower()
        df.loc[~df['sex'].isin(['male', 'female']), 'sex'] = pd.NA

    for col in ['bill_length_mm', 'bill_depth_mm', 'flipper_length_mm', 'body_mass_g', 'year']:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors='coerce')

    if 'body_mass_g' in df.columns:
        bm = df['body_mass_g']
        too_high = bm > 6500
        scaled = bm / 1000.0
        fixable = too_high & scaled.between(2500, 6500)
        df.loc[fixable, 'body_mass_g'] = scaled[fixable]
        df.loc[~df['body_mass_g'].between(2500, 6500), 'body_mass_g'] = pd.NA

    return df

def answer(df):
    d = clean(df)
    d = d[d['sex'].isin(['male', 'female'])]
    out = d.groupby('sex', dropna=True)['body_mass_g'].mean().dropna()
    return {str(k): float(v) for k, v in out.items()}
